// MCP `tools/call` requests validated against kit/operations.json, and a minimal Streamable HTTP
// client to send them. Part of a skill generated by spec2skill; plain ESM for Node.js 20+, no dependencies.
import { ArgsError, HttpError, guard, validateArgs } from './args.mjs';

export { ArgsError, HttpError, validateArgs };
const PROTOCOL = '2025-06-18';

/** The JSON-RPC `tools/call` request for one tool; throws ArgsError on bad arguments. */
export function buildCall(name, args = {}, id = 1) {
  validateArgs(name, args);
  return { jsonrpc: '2.0', id, method: 'tools/call', params: { name, arguments: args } };
}

/** POSTs one JSON-RPC message; returns the reply with the same id (JSON or SSE body) and the session id. */
async function post(endpoint, message, { session, headers, fetch }) {
  const res = await fetch(endpoint, {
    method: 'POST',
    headers: { 'content-type': 'application/json', accept: 'application/json, text/event-stream', 'mcp-protocol-version': PROTOCOL, ...(session && { 'mcp-session-id': session }), ...headers },
    body: JSON.stringify(message),
  });
  const text = await res.text();
  if (!res.ok) throw new HttpError(`${message.method}: ${endpoint} answered ${res.status}`, res.status, text);
  session = res.headers.get('mcp-session-id') ?? session;
  if (message.id === undefined) return { session };
  const sse = res.headers.get('content-type')?.includes('text/event-stream');
  const replies = sse ? text.split('\n').filter((l) => l.startsWith('data:')).map((l) => JSON.parse(l.slice(5))) : [JSON.parse(text)];
  const reply = replies.find((r) => r.id === message.id);
  if (!reply || reply.error) throw new HttpError(`${message.method}: ${reply?.error?.message ?? 'no reply'}`, res.status, reply?.error);
  return { result: reply.result, session };
}

/**
 * Calls one tool over Streamable HTTP (initialize, notifications/initialized, tools/call) and
 * returns its result. Refuses a destructive tool without `confirmed: true`.
 */
export async function callTool(endpoint, name, args = {}, { confirmed, headers = {}, fetch = globalThis.fetch } = {}) {
  guard(name, confirmed);
  const call = buildCall(name, args, 2);
  if (!endpoint) throw new ArgsError(`${name}: no MCP endpoint URL given`);
  const init = { jsonrpc: '2.0', id: 1, method: 'initialize', params: { protocolVersion: PROTOCOL, capabilities: {}, clientInfo: { name: 'spec2skill-kit', version: '1' } } };
  let { session } = await post(endpoint, init, { headers, fetch });
  ({ session } = await post(endpoint, { jsonrpc: '2.0', method: 'notifications/initialized' }, { session, headers, fetch }));
  const { result } = await post(endpoint, call, { session, headers, fetch });
  if (result?.isError) throw new HttpError(`${name}: the tool reported an error`, 200, result);
  return result;
}
